#!/usr/bin/env python3
"""Explicit offline oracle generation. Requires tokenizers==0.23.2.

Pass --scripts-source pointing to the pinned HF source file documented in
README.md. No model or Hub downloads occur. Tables are derived from actual
built-in pre-tokenizers, not the existing Oniguruma class tables.
"""
import argparse
import gzip
import hashlib
import json
from pathlib import Path
import random
import re
import subprocess

import tokenizers
from tokenizers import PreTokenizedString, Token, pre_tokenizers as pt

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent


def digest(data):
    return hashlib.sha256(data).hexdigest()


def tables(script_path):
    word, number, space, punct = pt.Whitespace(), pt.Digits(True), pt.WhitespaceSplit(), pt.Punctuation()
    runs, ascii_masks = [], []
    for cp in range(0x110000):
        if 0xD800 <= cp <= 0xDFFF:
            continue
        c = chr(cp)
        probe = "a" + c + "a"
        mask = (len(word.pre_tokenize_str(probe)) == 1)
        mask |= (len(number.pre_tokenize_str(probe)) == 3) << 1
        mask |= (len(space.pre_tokenize_str(c)) == 0) << 2
        mask |= (len(punct.pre_tokenize_str(probe)) == 3) << 3
        if cp < 128:
            ascii_masks.append(int(mask))
        elif mask:
            if runs and runs[-1][1] == cp-1 and runs[-1][2] == mask:
                runs[-1][1] = cp
            else:
                runs.append([cp, cp, int(mask)])
    source = script_path.read_bytes()
    # Source consists of disjoint literal ranges, followed by _ => Script::Any.
    entries = re.findall(r"0x([0-9A-Fa-f]+)(?:\.\.=0x([0-9A-Fa-f]+))?\s*=>\s*Script::(\w+)", source.decode())
    assert len(entries) > 1000
    names = sorted({name for _, _, name in entries} | {"Han"})
    ids = {name: i+1 for i, name in enumerate(names)}
    scripts = [0] * 0x110000
    for low, high, name in entries:
        if name in ("Hiragana", "Katakana"):
            name = "Han"
        a, b = int(low, 16), int(high or low, 16)
        scripts[a:b+1] = [ids[name]] * (b+1-a)
    scripts[0x20] = 0
    scripts[0x30FC] = ids["Han"]
    sruns = []
    for cp, kind in enumerate(scripts):
        if not kind:
            continue
        if sruns and sruns[-1][1] == cp-1 and sruns[-1][2] == kind:
            sruns[-1][1] = cp
        else:
            sruns.append([cp, cp, kind])
    out = ["// Code generated by testdata/pipeline/generate.py; DO NOT EDIT.",
           "// Built-in HF Tokenizers 0.23.2 profile; see testdata/pipeline/README.md.",
           "// Script data derived from HF Tokenizers (Apache-2.0); see NOTICE.",
           "package pipeline", "", "var asciiClasses = [128]uint8{"]
    out += [", ".join(map(str, ascii_masks[i:i+16])) + "," for i in range(0, 128, 16)]
    out += ["}", "", "var classRanges = [...]classRange{"]
    out += [f"{{0x{a:X}, 0x{b:X}, {m}}}," for a, b, m in runs]
    out += ["}", "", "var scriptRanges = [...]scriptRange{"]
    out += [f"{{0x{a:X}, 0x{b:X}, {m}}}," for a, b, m in sruns]
    out += ["}", ""]
    path = ROOT / "internal/pipeline/tables.go"
    path.write_text("\n".join(out))
    subprocess.run(["gofmt", "-w", str(path)], check=True)
    return digest(source)


def ranges(text):
    n = len(text.encode())
    result = {(0, n)}
    result.update((i, i+1) for i in range(n))
    if n <= 16:
        result.update((i, j) for i in range(n) for j in range(i+1, n+1))
    return sorted(result)


def capture(config, text):
    pre = None if config is None else pt.Whitespace()
    if pre is not None:
        pre.__setstate__(json.dumps(config).encode())
    subject = PreTokenizedString(text)
    if pre is not None:
        pre.pre_tokenize(subject)
    pieces = subject.get_splits(offset_referential="original", offset_type="byte")
    byte_at = [0]
    for c in text:
        byte_at.append(byte_at[-1] + len(c.encode()))
    result = []
    for value, offset, _ in pieces:
        if value:
            result.append({"text": value, "span": offset, "ranges": ranges(value)})
    # The Python binding's Encoding exposes original character offsets. Convert
    # these independently to original UTF-8 bytes, including partial-byte ranges.
    subject.tokenize(lambda s: [Token(i, "", r) for i, r in enumerate(ranges(s))] if s else [])
    offsets = iter(subject.to_encoding().offsets)
    for piece in result:
        mapped = []
        for a, b in piece["ranges"]:
            x, y = next(offsets)
            mapped.append([a, b, byte_at[x], byte_at[y]])
        piece["ranges"] = mapped
    return {"config": config, "input": text, "pieces": result}


def fixtures():
    configs = [None, {"type": "Sequence", "pretokenizers": []}]
    configs += [{"type": name} for name in ["Whitespace", "WhitespaceSplit", "BertPreTokenizer", "UnicodeScripts"]]
    configs += [{"type": "Digits", "individual_digits": b} for b in (False, True)]
    configs += [{"type": "CharDelimiterSplit", "delimiter": c} for c in ["x", "é", " "]]
    for entry in json.loads((ROOT / "testdata/corpus_patterns.json").read_text()):
        configs.append({"type":"Split", "pattern":{"Regex":entry["pattern"]}, "behavior":"Isolated", "invert":False})
    for behavior in ["Removed", "Isolated", "Contiguous", "MergedWithPrevious", "MergedWithNext"]:
        configs.append({"type": "Punctuation", "behavior": behavior})
        for pattern in [{"String": "--"}, {"String": "é"}, {"Regex": "[0-9]"}, {"Regex": "[0-9][0-9][0-9]"}]:
            for invert in (False, True):
                configs.append({"type": "Split", "pattern": pattern, "behavior": behavior, "invert": invert})
    for prefix in (False, True):
        for regex in (False, True):
            configs.append({"type": "ByteLevel", "add_prefix_space": prefix, "trim_offsets": True, "use_regex": regex})
    for scheme in ["always", "first", "never"]:
        for split in (False, True):
            for replacement in ["▁", "_", "é"]:
                configs.append({"type": "Metaspace", "replacement": replacement, "prepend_scheme": scheme, "split": split})
    split = {"type": "Split", "pattern": {"Regex": "[0-9]"}, "behavior": "Isolated", "invert": False}
    byte = {"type": "ByteLevel", "add_prefix_space": False, "trim_offsets": False, "use_regex": False}
    meta = {"type": "Metaspace", "replacement": "▁", "prepend_scheme": "first", "split": True}
    for children in [[split, byte], [split, meta], [byte, meta], [meta, byte], [byte, byte],
                     [meta, split, meta], [{"type":"WhitespaceSplit"}, meta],
                     [{"type":"Punctuation"}, byte, {"type":"Digits","individual_digits":True}],
                     [byte, {"type":"CharDelimiterSplit","delimiter":"Ã"}, meta]]:
        configs.append({"type": "Sequence", "pretokenizers": children})
    seeds = ["", "a", "ab12é", "é😀中", "  ", "\r\n\t", " a  b ", "a--b---c--",
             "a!!b$€🙂", "ééé", "▁a ▁b", "1234567x12", "a²Ⅳ٣b", "a_b\u200db",
             "e\u0301a", "日本ー語 abcПривет", "\u00a0x\u2028 y", "I'm I'M we're WE'RE", "\U0001e4d0 a"]
    rng = random.Random(9271)
    alphabet = " a9é²!\n\r\t▁_中ー\u0301\u200d😀"
    seeds += ["".join(rng.choice(alphabet) for _ in range(rng.randrange(1, 14))) for _ in range(12)]
    cases = [capture(c, text) for c in configs for text in seeds]
    # Independently composed pipelines catch interactions that single-stage
    # fixtures and local Walk/WalkText parity cannot establish.
    choices = [c for c in configs if c and c["type"] != "Sequence"]
    for _ in range(1000):
        children = [rng.choice(choices) for _ in range(rng.randrange(1, 5))]
        config = {"type": "Sequence", "pretokenizers": children}
        text = "".join(rng.choice(alphabet) for _ in range(rng.randrange(1, 32)))
        cases.append(capture(config, text))
    # Buffer growth and long-piece tails, without quadratic all-range fixtures.
    for config in [byte, meta, {"type":"ByteLevel","add_prefix_space":True,"use_regex":True,"trim_offsets":False}]:
        cases.append(capture(config, ("é 😀word123\n" * 257)))
    data = (json.dumps(cases, ensure_ascii=False, separators=(",", ":")) + "\n").encode()
    (HERE / "cases.json.gz").write_bytes(gzip.compress(data, mtime=0))
    return len(cases), digest(data)


if __name__ == "__main__":
    assert tokenizers.__version__ == "0.23.2"
    parser = argparse.ArgumentParser()
    parser.add_argument("--scripts-source", type=Path)
    parser.add_argument("--fixtures-only", action="store_true")
    args = parser.parse_args()
    manifest_path = HERE / "manifest.json"
    manifest = json.loads(manifest_path.read_text()) if manifest_path.exists() else {}
    if not args.fixtures_only:
        assert args.scripts_source is not None
        source_hash = digest(args.scripts_source.read_bytes())
        if "scripts_source_sha256" in manifest:
            assert manifest["scripts_source_sha256"] == source_hash, "wrong HF script source"
        tables(args.scripts_source)
        manifest["scripts_source_sha256"] = source_hash
    count, cases_hash = fixtures()
    native = next(Path(tokenizers.__file__).parent.glob("*.so"))
    manifest.update(oracle="tokenizers", version=tokenizers.__version__, native_sha256=digest(native.read_bytes()),
                    case_count=count, cases_sha256=cases_hash,
                    tables_sha256=digest((ROOT / "internal/pipeline/tables.go").read_bytes()),
                    source="https://github.com/huggingface/tokenizers/blob/v0.23.2/tokenizers/src/pre_tokenizers/unicode_scripts/scripts.rs")
    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Generated {count} cases; format tables.go with gofmt.")
